import{_ as a,I as o,o as g,c as h,b6 as d,J as r}from"./chunks/framework.COUcLbTA.js";const v=JSON.parse('{"title":"Embedding 与向量检索","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/8-artificial-intelligence/embedding-vector-retrieval.md","filePath":"zh-cn/appendix/8-artificial-intelligence/embedding-vector-retrieval.md"}'),b={name:"zh-cn/appendix/8-artificial-intelligence/embedding-vector-retrieval.md"};function c(p,t,u,m,_,q){const e=o("EmbeddingConceptDemo"),n=o("VectorSimilarityDemo"),i=o("VectorIndexDemo"),l=o("VectorDatabaseDemo"),s=o("EmbeddingPipelineDemo");return g(),h("div",null,[t[0]||(t[0]=d('<h1 id="embedding-与向量检索" tabindex="-1">Embedding 与向量检索 <a class="header-anchor" href="#embedding-与向量检索" aria-label="Permalink to “Embedding 与向量检索”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>计算机怎么理解&quot;猫和狗很像，但和汽车不像&quot;这件事？</strong> 对人类来说这是常识，但对计算机来说，&quot;猫&quot;、&quot;狗&quot;、&quot;汽车&quot;不过是三个毫无关联的字符串。Embedding（嵌入）技术就是解决这个问题的关键——它把文字变成数字向量，让计算机也能理解语义上的&quot;远近亲疏&quot;。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>直觉理解</strong>：明白 Embedding 是什么，为什么&quot;猫&quot;和&quot;狗&quot;的向量会靠近</li><li><strong>相似度计算</strong>：掌握余弦相似度、欧氏距离等核心度量方法</li><li><strong>索引原理</strong>：理解向量数据库如何在百万级数据中毫秒级检索</li><li><strong>技术选型</strong>：了解主流向量数据库的特点和适用场景</li><li><strong>端到端流程</strong>：掌握从文本到向量到检索的完整 Pipeline</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>Embedding 概念</td><td>语义空间、向量表示</td></tr><tr><td><strong>第 2 章</strong></td><td>相似度计算</td><td>余弦相似度、欧氏距离</td></tr><tr><td><strong>第 3 章</strong></td><td>向量索引</td><td>暴力搜索 vs ANN</td></tr><tr><td><strong>第 4 章</strong></td><td>向量数据库</td><td>Pinecone、Milvus、Chroma</td></tr><tr><td><strong>第 5 章</strong></td><td>端到端 Pipeline</td><td>文本→向量→存储→查询</td></tr></tbody></table><hr><h2 id="_0-全景图-从文字到数字的桥梁" tabindex="-1">0. 全景图：从文字到数字的桥梁 <a class="header-anchor" href="#_0-全景图-从文字到数字的桥梁" aria-label="Permalink to “0. 全景图：从文字到数字的桥梁”">​</a></h2><p>在自然语言处理的世界里，有一个根本性的挑战：<strong>计算机只认识数字，不认识文字</strong>。</p><p>早期的做法是给每个词分配一个编号（One-Hot 编码），比如&quot;猫&quot;=001，&quot;狗&quot;=010，&quot;汽车&quot;=100。但这样做有个致命问题：<strong>所有词之间的距离都一样远</strong>。&quot;猫&quot;到&quot;狗&quot;的距离和&quot;猫&quot;到&quot;汽车&quot;的距离完全相同——这显然不符合我们的直觉。</p><p>Embedding 的革命性在于：它把每个词映射到一个<strong>稠密的低维向量空间</strong>，让语义相近的词自然聚集在一起。在这个空间里，&quot;猫&quot;和&quot;狗&quot;靠得很近，而&quot;汽车&quot;则在远处——计算机终于能&quot;理解&quot;语义了。</p><div class="tip custom-block"><p class="custom-block-title">从 One-Hot 到 Embedding 的飞跃</p><ul><li><strong>One-Hot</strong>：维度 = 词表大小（可能几万维），每个向量只有一个 1，其余全是 0，稀疏且无语义</li><li><strong>Embedding</strong>：维度通常 768~1536，每个数字都有意义，稠密且富含语义信息</li><li><strong>关键突破</strong>：Word2Vec（2013）证明了&quot;词的含义可以用它的上下文来定义&quot;，开启了 Embedding 时代</li></ul></div><hr><h2 id="_1-embedding-概念-把文字变成坐标" tabindex="-1">1. Embedding 概念：把文字变成坐标 <a class="header-anchor" href="#_1-embedding-概念-把文字变成坐标" aria-label="Permalink to “1. Embedding 概念：把文字变成坐标”">​</a></h2><p>Embedding 的核心思想可以用一句话概括：<strong>用一组数字（向量）来表示一个词或句子的含义</strong>。</p><p>想象一个二维坐标系。我们把&quot;猫&quot;放在坐标 (0.2, 0.7)，&quot;狗&quot;放在 (0.3, 0.6)，&quot;汽车&quot;放在 (0.9, 0.1)。你会发现&quot;猫&quot;和&quot;狗&quot;的坐标很接近，而&quot;汽车&quot;离它们很远。这就是 Embedding 的直觉——<strong>语义相似度变成了空间距离</strong>。</p>',16)),r(e),t[1]||(t[1]=d('<div class="tip custom-block"><p class="custom-block-title">Embedding 的三个关键特性</p><ol><li><strong>语义聚类</strong>：相似含义的词会自动聚集在一起（动物一簇、食物一簇、科技一簇）</li><li><strong>类比关系</strong>：向量运算可以表达语义关系，经典例子：king - man + woman ≈ queen</li><li><strong>维度含义</strong>：每个维度隐式编码了某种语义特征（如&quot;是否是动物&quot;、&quot;大小&quot;、&quot;情感倾向&quot;等）</li></ol></div><table tabindex="0"><thead><tr><th>编码方式</th><th>维度</th><th>语义信息</th><th>典型应用</th></tr></thead><tbody><tr><td>One-Hot</td><td>词表大小（~50000）</td><td>无</td><td>传统 NLP</td></tr><tr><td>Word2Vec</td><td>100~300</td><td>词级语义</td><td>词相似度、类比推理</td></tr><tr><td>BERT Embedding</td><td>768</td><td>上下文语义</td><td>句子理解、问答</td></tr><tr><td>OpenAI text-embedding-3</td><td>1536~3072</td><td>深层语义</td><td>RAG、语义搜索</td></tr></tbody></table><hr><h2 id="_2-相似度计算-向量之间有多-近" tabindex="-1">2. 相似度计算：向量之间有多&quot;近&quot;？ <a class="header-anchor" href="#_2-相似度计算-向量之间有多-近" aria-label="Permalink to “2. 相似度计算：向量之间有多&quot;近&quot;？”">​</a></h2><p>有了向量表示，下一个问题自然是：<strong>怎么衡量两个向量有多相似？</strong> 这就像在地图上衡量两个城市有多近——你可以量直线距离，也可以看方向是否一致。</p>',5)),r(n),t[2]||(t[2]=d('<div class="tip custom-block"><p class="custom-block-title">两种核心度量</p><ul><li><strong>余弦相似度（Cosine Similarity）</strong>：衡量两个向量的<strong>方向</strong>是否一致，值域 [-1, 1]。1 表示方向完全相同，0 表示正交（无关），-1 表示完全相反。文本语义比较的首选，因为它不受向量长度影响。</li><li><strong>欧氏距离（Euclidean Distance）</strong>：衡量两个向量端点之间的<strong>直线距离</strong>，值域 [0, ∞)。0 表示完全重合，值越大越不相似。适合需要考虑&quot;绝对大小&quot;的场景。</li></ul></div><table tabindex="0"><thead><tr><th>度量方式</th><th>公式直觉</th><th>值域</th><th>适用场景</th></tr></thead><tbody><tr><td>余弦相似度</td><td>看方向，忽略长度</td><td>[-1, 1]</td><td>文本语义搜索、推荐系统</td></tr><tr><td>欧氏距离</td><td>看端点直线距离</td><td>[0, ∞)</td><td>图像特征、聚类分析</td></tr><tr><td>点积</td><td>方向 × 长度</td><td>(-∞, +∞)</td><td>归一化向量的快速计算</td></tr><tr><td>曼哈顿距离</td><td>沿坐标轴走的距离</td><td>[0, ∞)</td><td>高维稀疏向量</td></tr></tbody></table><hr><h2 id="_3-向量索引-如何在百万向量中毫秒检索" tabindex="-1">3. 向量索引：如何在百万向量中毫秒检索？ <a class="header-anchor" href="#_3-向量索引-如何在百万向量中毫秒检索" aria-label="Permalink to “3. 向量索引：如何在百万向量中毫秒检索？”">​</a></h2><p>假设你有 100 万条文档，每条都转成了 1536 维的向量。用户提了一个问题，你需要找到最相似的 10 条。最直接的方法是逐一计算相似度——但这意味着要做 100 万次 1536 维的向量运算，太慢了。</p><p>这就是<strong>向量索引</strong>要解决的问题：<strong>用空间换时间，通过预处理建立索引结构，让检索速度从 O(n) 降到近似 O(log n)</strong>。</p>',6)),r(i),t[3]||(t[3]=d('<div class="tip custom-block"><p class="custom-block-title">暴力搜索 vs 近似最近邻（ANN）</p><ul><li><strong>暴力搜索（Flat）</strong>：逐一比较，100% 准确但速度慢。适合数据量小（&lt; 10 万）的场景。</li><li><strong>IVF（倒排文件索引）</strong>：先把向量空间划分成若干区域（聚类），查询时只搜索最近的几个区域。像是把图书馆按主题分区，找书时只去相关区域。</li><li><strong>HNSW（分层可导航小世界图）</strong>：构建多层图结构，从粗粒度到细粒度逐层导航。像是先看世界地图定位到国家，再看省级地图，最后看街道地图。</li><li><strong>PQ（乘积量化）</strong>：把高维向量压缩成短编码，牺牲少量精度换取大幅内存节省。适合超大规模数据集。</li></ul></div><table tabindex="0"><thead><tr><th>索引类型</th><th>构建速度</th><th>查询速度</th><th>召回率</th><th>内存占用</th><th>适用规模</th></tr></thead><tbody><tr><td>Flat（暴力）</td><td>无需构建</td><td>慢</td><td>100%</td><td>高</td><td>&lt; 10 万</td></tr><tr><td>IVF</td><td>中等</td><td>快</td><td>95%+</td><td>中</td><td>10 万~1000 万</td></tr><tr><td>HNSW</td><td>慢</td><td>很快</td><td>99%+</td><td>高</td><td>10 万~1000 万</td></tr><tr><td>PQ</td><td>中等</td><td>快</td><td>90%+</td><td>很低</td><td>&gt; 1000 万</td></tr><tr><td>IVF-PQ</td><td>中等</td><td>快</td><td>92%+</td><td>低</td><td>&gt; 1 亿</td></tr></tbody></table><hr><h2 id="_4-向量数据库-专为向量而生的存储引擎" tabindex="-1">4. 向量数据库：专为向量而生的存储引擎 <a class="header-anchor" href="#_4-向量数据库-专为向量而生的存储引擎" aria-label="Permalink to “4. 向量数据库：专为向量而生的存储引擎”">​</a></h2><p>有了向量和索引算法，你需要一个地方来存储和管理它们。传统数据库（MySQL、PostgreSQL）擅长处理结构化数据，但对高维向量的相似度搜索力不从心。<strong>向量数据库</strong>就是为这个场景专门设计的。</p>',5)),r(l),t[4]||(t[4]=d('<div class="tip custom-block"><p class="custom-block-title">向量数据库的核心能力</p><ol><li><strong>高效存储</strong>：针对高维浮点向量优化的存储格式</li><li><strong>ANN 检索</strong>：内置多种近似最近邻索引算法（HNSW、IVF 等）</li><li><strong>元数据过滤</strong>：支持在向量搜索的同时按标签、时间等条件过滤</li><li><strong>实时更新</strong>：支持动态增删改向量，无需重建整个索引</li><li><strong>水平扩展</strong>：分布式架构支持亿级向量规模</li></ol></div><table tabindex="0"><thead><tr><th>数据库</th><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>Pinecone</td><td>全托管云服务</td><td>零运维、开箱即用</td><td>快速原型、中小规模生产</td></tr><tr><td>Milvus</td><td>开源分布式</td><td>高性能、可扩展</td><td>大规模生产环境</td></tr><tr><td>Chroma</td><td>开源轻量</td><td>嵌入式、API 简洁</td><td>本地开发、小型项目</td></tr><tr><td>Weaviate</td><td>开源云原生</td><td>内置向量化、GraphQL</td><td>需要自动向量化的场景</td></tr><tr><td>Qdrant</td><td>开源高性能</td><td>Rust 实现、过滤强</td><td>需要复杂过滤的场景</td></tr><tr><td>pgvector</td><td>PG 扩展</td><td>复用现有 PG 基础设施</td><td>已有 PostgreSQL 的团队</td></tr></tbody></table><hr><h2 id="_5-端到端-pipeline-从文本到检索的完整流程" tabindex="-1">5. 端到端 Pipeline：从文本到检索的完整流程 <a class="header-anchor" href="#_5-端到端-pipeline-从文本到检索的完整流程" aria-label="Permalink to “5. 端到端 Pipeline：从文本到检索的完整流程”">​</a></h2><p>理解了各个组件后，让我们把它们串起来，看看一个完整的向量检索系统是怎么工作的。</p><p>整个流程分为两条线：<strong>离线写入</strong>（把文档变成向量存起来）和<strong>在线查询</strong>（把问题变成向量去搜索）。</p>',6)),r(s),t[5]||(t[5]=d('<div class="tip custom-block"><p class="custom-block-title">离线写入流程</p><ol><li><strong>文档加载</strong>：从各种来源（PDF、网页、数据库）读取原始文本</li><li><strong>文本预处理</strong>：清洗、去噪、标准化（去掉 HTML 标签、特殊字符等）</li><li><strong>文本分块</strong>：按策略将长文本切分为合适大小的片段（200~500 tokens）</li><li><strong>向量化</strong>：调用嵌入模型（如 OpenAI text-embedding-3-small）将每个片段转为向量</li><li><strong>存入向量数据库</strong>：将向量和原始文本、元数据一起写入数据库</li></ol></div><div class="tip custom-block"><p class="custom-block-title">在线查询流程</p><ol><li><strong>接收查询</strong>：用户输入自然语言问题</li><li><strong>查询向量化</strong>：用同一个嵌入模型将问题转为向量</li><li><strong>相似度检索</strong>：在向量数据库中搜索 Top-K 最相似的文档片段</li><li><strong>后处理</strong>：重排序、去重、元数据过滤</li><li><strong>返回结果</strong>：将最相关的文档片段返回给调用方（或交给 LLM 生成回答）</li></ol></div><table tabindex="0"><thead><tr><th>环节</th><th>关键选择</th><th>推荐方案</th></tr></thead><tbody><tr><td>嵌入模型</td><td>精度 vs 成本 vs 速度</td><td>OpenAI text-embedding-3-small（性价比高）</td></tr><tr><td>分块策略</td><td>粒度 vs 语义完整性</td><td>递归分块，200~500 tokens</td></tr><tr><td>向量数据库</td><td>规模 vs 运维成本</td><td>小项目用 Chroma，生产用 Pinecone/Milvus</td></tr><tr><td>相似度度量</td><td>语义 vs 精确</td><td>余弦相似度（文本场景首选）</td></tr><tr><td>Top-K 值</td><td>召回率 vs 噪音</td><td>先检索 20 条，重排序后取 Top 5</td></tr></tbody></table><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>Embedding 与向量检索是连接&quot;人类语言&quot;和&quot;机器理解&quot;的桥梁，也是 RAG、语义搜索、推荐系统等 AI 应用的基础设施。</p><p>回顾本章的关键要点：</p><ol><li><strong>Embedding 的本质</strong>：把文本映射到高维向量空间，让语义相似度变成空间距离</li><li><strong>相似度度量</strong>：余弦相似度关注方向（适合文本），欧氏距离关注绝对距离</li><li><strong>索引是性能关键</strong>：HNSW 和 IVF 让百万级向量的检索降到毫秒级</li><li><strong>向量数据库选型</strong>：小项目用 Chroma/pgvector，生产环境用 Pinecone/Milvus</li><li><strong>端到端思维</strong>：从文档加载到最终检索，每个环节的选择都会影响最终效果</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://platform.openai.com/docs/guides/embeddings" target="_blank" rel="noreferrer">OpenAI Embeddings 文档</a> - 官方嵌入模型使用指南</li><li><a href="https://www.pinecone.io/learn/" target="_blank" rel="noreferrer">Pinecone Learning Center</a> - 向量数据库和检索的系统教程</li><li><a href="https://github.com/facebookresearch/faiss/wiki" target="_blank" rel="noreferrer">FAISS Wiki</a> - Facebook 开源的向量检索库文档</li><li><a href="https://arxiv.org/abs/1301.3781" target="_blank" rel="noreferrer">Word2Vec 原始论文</a> - Embedding 时代的开山之作</li><li><a href="https://huggingface.co/spaces/mteb/leaderboard" target="_blank" rel="noreferrer">MTEB 排行榜</a> - 嵌入模型性能对比排行榜</li></ul>',10))])}const T=a(b,[["render",c]]);export{v as __pageData,T as default};
